//! Parity of multi-output MC sampling, MC objectives and outcome constraints
//! with BoTorch (fixtures in `tests/fixtures/phase4b/*.json`, generated by
//! `scripts/generate_fixtures.py --phase 4b`).
//!
//! * posterior samples from explicit multi-output base samples (BoTorch's
//!   `S × q × m` layout and per-output covariance roots);
//! * values and gradients of qEI, qPI, qSR, qUCB and qLogEI with linear,
//!   generic and constrained (`ConstrainedMCObjective`) objectives, and of
//!   qEI, qPI, qLogEI and qLogProbabilityOfFeasibility with outcome
//!   constraints (scalar and per-constraint `eta`, `fat` true / false / a list
//!   with probability constraints), for `q` = 1, 2 with and without pending
//!   points, on multi-output, single-output and `ModelListGP` models;
//! * qLogNEI with objectives and constraints, incremental or not, including
//!   baselines that are infeasible in some or all samples (BoTorch's lower
//!   bound of the objective at recorded points);
//! * `prune_inferior_points` with objectives and constraints (also when no
//!   point is feasible) and `get_infeasible_cost`.
//!
//! All MC quantities use BoTorch's recorded base samples. Errors are mixed
//! elementwise/normwise relative errors (`common::rel_err`); log-space values
//! are compared by `|a - e| / max(|e|, 1)`. Run with `--nocapture` to print the
//! error tables.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::{
    get_infeasible_cost, prune_inferior_points_indices, AcquisitionFunction,
    ConstrainedMcObjective, GenericMcObjective, LinearMcObjective, McAcquisitionOptions,
    McObjective, PruneOptions, QExpectedImprovement, QLogExpectedImprovement,
    QLogExpectedImprovementOptions, QLogNoisyExpectedImprovement,
    QLogNoisyExpectedImprovementOptions, QLogProbabilityOfFeasibility,
    QLogProbabilityOfFeasibilityOptions, QProbabilityOfImprovement, QSimpleRegret,
    QUpperConfidenceBound,
};
use botorch_core::sampling::SobolQMCNormalSampler;
use botorch_core::utils::objective::{
    FnOutcomeConstraint, LinearOutcomeConstraint, McConstraint, OutcomeConstraints,
};
use botorch_core::utils::safe_math::sigmoid;
use botorch_core::{
    BatchedInputTransform, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, KernelKind, Matrix,
    Model, ModelListGP, Normalize, OutcomeTransformChoice, Vector,
};
use common::*;
use serde::Deserialize;

/// Tolerance for deterministic quantities.
const RTOL: f64 = 1e-10;
/// Absolute agreement threshold for gradient entries.
const GRAD_ATOL: f64 = 1e-14;

#[derive(Debug, Deserialize, Clone)]
#[serde(tag = "type", rename_all = "lowercase")]
enum ObjectiveSpec {
    Linear {
        weights: Vec<f64>,
    },
    Quadratic {
        a: Vec<f64>,
        b: Vec<f64>,
        c: f64,
    },
    Constrained {
        objective: Box<ObjectiveSpec>,
        constraints: Vec<ConstraintSpec>,
        infeasible_cost: f64,
        eta: Vec<f64>,
    },
}

#[derive(Debug, Deserialize, Clone)]
#[serde(tag = "type", rename_all = "lowercase")]
enum ConstraintSpec {
    Linear {
        weights: Vec<f64>,
        offset: f64,
    },
    Quadratic {
        a: Vec<f64>,
        b: Vec<f64>,
        c: f64,
    },
    Probability {
        index: usize,
        scale: f64,
        shift: f64,
    },
}

/// `c + Σ a_t y_t + Σ b_t y_t²` (in torch's order) and its gradient.
fn quadratic(a: &[f64], b: &[f64], c: f64, y: &[f64]) -> (f64, Vec<f64>) {
    let s1: f64 = y.iter().zip(a).map(|(y, a)| y * a).sum();
    let s2: f64 = y.iter().zip(b).map(|(y, b)| y * y * b).sum();
    let g = y
        .iter()
        .zip(a.iter().zip(b))
        .map(|(y, (a, b))| a + 2.0 * b * y)
        .collect();
    (c + s1 + s2, g)
}

fn build_objective(spec: &ObjectiveSpec) -> Arc<dyn McObjective> {
    match spec.clone() {
        ObjectiveSpec::Linear { weights } => {
            Arc::new(LinearMcObjective::new(Vector::from_vec(weights)).unwrap())
        }
        ObjectiveSpec::Quadratic { a, b, c } => {
            Arc::new(GenericMcObjective::new(move |y| quadratic(&a, &b, c, y)))
        }
        ObjectiveSpec::Constrained {
            objective,
            constraints,
            infeasible_cost,
            eta,
        } => Arc::new(
            ConstrainedMcObjective::new(
                build_objective(&objective),
                constraints.iter().map(build_constraint).collect(),
                infeasible_cost,
                eta,
            )
            .unwrap(),
        ),
    }
}

fn build_constraint(spec: &ConstraintSpec) -> Arc<dyn McConstraint> {
    match spec.clone() {
        ConstraintSpec::Linear { weights, offset } => {
            Arc::new(LinearOutcomeConstraint::new(Vector::from_vec(weights), offset).unwrap())
        }
        ConstraintSpec::Quadratic { a, b, c } => {
            Arc::new(FnOutcomeConstraint::new(move |y| quadratic(&a, &b, c, y)))
        }
        ConstraintSpec::Probability {
            index,
            scale,
            shift,
        } => Arc::new(FnOutcomeConstraint::new(move |y| {
            let s = sigmoid(scale * (y[index] - shift));
            let mut g = vec![0.0; y.len()];
            g[index] = (1.0 - s) * s * scale;
            (s, g)
        })),
    }
}

#[derive(Debug, Deserialize)]
struct Config {
    d: usize,
    m: usize,
    covar: String,
    normalize: Option<String>,
    outcome: String,
    bounds: Option<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct ModelSpec {
    config: Config,
    train_x: Vec<Vec<Vec<f64>>>,
    train_y: Vec<Vec<Vec<f64>>>,
    train_yvar: Option<Vec<Vec<Vec<f64>>>>,
    raw_params: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct SamplesFixture {
    x: Vec<Vec<f64>>,
    base_samples: Vec<Vec<f64>>,
    samples: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct McResult {
    acqf: String,
    objective: Option<ObjectiveSpec>,
    constraints: Option<Vec<ConstraintSpec>>,
    eta: Option<Vec<f64>>,
    best_f: Option<f64>,
    tau: Option<f64>,
    beta: Option<f64>,
    fat: Option<bool>,
    fat_list: Option<Vec<Option<bool>>>,
    value: f64,
    grad: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct McCase {
    x: Vec<Vec<f64>>,
    x_pending: Option<Vec<Vec<f64>>>,
    base_samples: Vec<Vec<f64>>,
    results: Vec<McResult>,
}

#[derive(Debug, Deserialize)]
struct NeiCase {
    q: usize,
    x: Vec<Vec<f64>>,
    x_pending: Option<Vec<Vec<f64>>>,
    incremental: bool,
    objective: Option<ObjectiveSpec>,
    constraints: Option<Vec<ConstraintSpec>>,
    eta: Option<Vec<f64>>,
    base_samples: Vec<Vec<f64>>,
    value: f64,
    grad: Vec<Vec<f64>>,
    infeasible_samples: usize,
}

#[derive(Debug, Deserialize)]
struct NeiFixture {
    lower_bound_points: Vec<Vec<f64>>,
    cases: Vec<NeiCase>,
}

#[derive(Debug, Deserialize)]
struct PruneCase {
    objective: Option<ObjectiveSpec>,
    constraints: Option<Vec<ConstraintSpec>>,
    base_samples: Vec<Vec<f64>>,
    indices: Vec<usize>,
}

#[derive(Debug, Deserialize)]
struct CostCase {
    objective: Option<ObjectiveSpec>,
    value: f64,
}

#[derive(Debug, Deserialize)]
struct PruneFixture {
    x: Vec<Vec<f64>>,
    cases: Vec<PruneCase>,
    infeasible_cost_x: Vec<Vec<f64>>,
    infeasible_cost: Vec<CostCase>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    name: String,
    kind: String,
    models: Vec<ModelSpec>,
    baseline_x: Vec<Vec<f64>>,
    samples: SamplesFixture,
    mc: Vec<McCase>,
    nei: NeiFixture,
    prune: PruneFixture,
}

fn load() -> Vec<Fixture> {
    let dir: PathBuf = fixture_dir().join("phase4b");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("phase-4b fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.extension().is_some_and(|e| e == "json")
                && p.file_name()
                    .is_some_and(|n| n.to_string_lossy().starts_with("mc_"))
        })
        .collect();
    paths.sort();
    assert!(paths.len() >= 5, "phase-4b fixtures are missing");
    paths
        .iter()
        .map(|p| {
            serde_json::from_str(&std::fs::read_to_string(p).unwrap())
                .unwrap_or_else(|e| panic!("failed to parse {}: {e}", p.display()))
        })
        .collect()
}

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        other => panic!("unknown covar {other}"),
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some("explicit") => Some(BatchedInputTransform::Shared(
            Normalize::with_bounds(&matrix(c.bounds.as_ref().unwrap())).unwrap(),
        )),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_model(f: &Fixture) -> Arc<dyn Model> {
    let members: Vec<BatchedMultiOutputGP> = f.models.iter().map(build_member).collect();
    match f.kind.as_str() {
        "single_task" => Arc::new(members.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(members).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

fn sampler_from(base: &[Vec<f64>]) -> Option<Arc<SobolQMCNormalSampler>> {
    Some(Arc::new(
        SobolQMCNormalSampler::from_base_samples(matrix(base), Some(0)).unwrap(),
    ))
}

fn log_err(a: f64, e: f64) -> f64 {
    (a - e).abs() / e.abs().max(1.0)
}

fn constraints_of(
    specs: &Option<Vec<ConstraintSpec>>,
    eta: &Option<Vec<f64>>,
) -> Option<OutcomeConstraints> {
    specs.as_ref().map(|cs| {
        OutcomeConstraints::new(
            cs.iter().map(build_constraint).collect(),
            eta.clone().expect("eta"),
        )
        .unwrap()
    })
}

fn mc_acqf(
    model: Arc<dyn Model>,
    c: &McResult,
    base: &[Vec<f64>],
    pending: Option<Matrix>,
) -> Box<dyn AcquisitionFunction> {
    let objective = c.objective.as_ref().map(build_objective);
    let constraints = constraints_of(&c.constraints, &c.eta);
    let opts = McAcquisitionOptions {
        sampler: sampler_from(base),
        x_pending: pending.clone(),
        objective: objective.clone(),
        constraints: constraints.clone(),
    };
    match c.acqf.as_str() {
        "qExpectedImprovement" => {
            Box::new(QExpectedImprovement::new(model, c.best_f.unwrap(), opts).unwrap())
        }
        "qProbabilityOfImprovement" => Box::new(
            QProbabilityOfImprovement::new(model, c.best_f.unwrap(), c.tau.unwrap(), opts).unwrap(),
        ),
        "qSimpleRegret" => Box::new(QSimpleRegret::new(model, opts).unwrap()),
        "qUpperConfidenceBound" => {
            Box::new(QUpperConfidenceBound::new(model, c.beta.unwrap(), opts).unwrap())
        }
        "qLogExpectedImprovement" => Box::new(
            QLogExpectedImprovement::new(
                model,
                c.best_f.unwrap(),
                QLogExpectedImprovementOptions {
                    sampler: sampler_from(base),
                    x_pending: pending,
                    fat: c.fat.unwrap_or(true),
                    objective,
                    constraints,
                    constraint_fat: c.fat_list.clone(),
                    ..Default::default()
                },
            )
            .unwrap(),
        ),
        "qLogProbabilityOfFeasibility" => Box::new(
            QLogProbabilityOfFeasibility::new(
                model,
                constraints.unwrap(),
                QLogProbabilityOfFeasibilityOptions {
                    sampler: sampler_from(base),
                    x_pending: pending,
                    ..Default::default()
                },
            )
            .unwrap(),
        ),
        other => panic!("unknown acquisition function {other}"),
    }
}

fn label(c: &McResult) -> String {
    let obj = match &c.objective {
        None => "none",
        Some(ObjectiveSpec::Linear { .. }) => "linear",
        Some(ObjectiveSpec::Quadratic { .. }) => "generic",
        Some(ObjectiveSpec::Constrained { .. }) => "constrained",
    };
    let cons = c.constraints.as_ref().map_or(0, |c| c.len());
    let fat = match (&c.fat_list, c.fat) {
        (Some(_), _) => " fat=list",
        (None, Some(false)) => " fat=false",
        _ => "",
    };
    format!("{} obj={obj} cons={cons}{fat}", c.acqf)
}

#[test]
fn parity_multi_output_samples() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let post = model.posterior(&matrix(&f.samples.x), false).unwrap();
        let s = post
            .rsample_from_base_samples(&matrix(&f.samples.base_samples))
            .unwrap();
        let rm = s.to_row_major();
        let expected = flatten(&f.samples.samples);
        r.check_slices(&f.name, "samples from base samples", &rm, &expected, RTOL);
    }
    r.finish("multi-output samples");
}

#[test]
fn parity_mc_objectives_and_constraints() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        for case in &f.mc {
            let x = matrix(&case.x);
            let pending = case.x_pending.as_ref().map(|p| matrix(p));
            for c in &case.results {
                let acqf = mc_acqf(model.clone(), c, &case.base_samples, pending.clone());
                let (v, g) = acqf.forward_with_grad(&x).unwrap();
                assert_eq!(acqf.forward(&x).unwrap(), v);
                let tag = label(c);
                let q = x.nrows();
                let pq = if pending.is_some() {
                    format!("q={q}+p")
                } else {
                    format!("q={q}")
                };
                if acqf.is_log() {
                    r.check(
                        &f.name,
                        &format!("{tag} {pq} value"),
                        log_err(v, c.value),
                        RTOL,
                    );
                } else {
                    r.check_slices(
                        &f.name,
                        &format!("{tag} {pq} value"),
                        &[v],
                        &[c.value],
                        RTOL,
                    );
                }
                r.check_slices_atol(
                    &f.name,
                    &format!("{tag} {pq} grad"),
                    &matrix_rows(&g),
                    &flatten(&c.grad),
                    RTOL,
                    GRAD_ATOL,
                );
            }
        }
    }
    r.finish("MC objectives and outcome constraints");
}

#[test]
fn parity_qlognei_with_objectives_and_constraints() {
    let mut r = Report::default();
    let mut infeasible_cases = 0;
    for f in load() {
        let model = build_model(&f);
        let xb = matrix(&f.baseline_x);
        for (k, c) in f.nei.cases.iter().enumerate() {
            let options = QLogNoisyExpectedImprovementOptions {
                sampler: sampler_from(&c.base_samples),
                x_pending: c.x_pending.as_ref().map(|p| matrix(p)),
                prune_baseline: false,
                incremental: c.incremental,
                objective: c.objective.as_ref().map(build_objective),
                constraints: constraints_of(&c.constraints, &c.eta),
                lower_bound_points: Some(matrix(&f.nei.lower_bound_points)),
                ..Default::default()
            };
            let acqf = QLogNoisyExpectedImprovement::new(model.clone(), &xb, options).unwrap();
            let x = matrix(&c.x);
            assert_eq!(x.nrows(), c.q);
            let (v, g) = acqf.forward_with_grad(&x).unwrap();
            assert_eq!(acqf.forward(&x).unwrap(), v);
            if c.infeasible_samples > 0 {
                infeasible_cases += 1;
            }
            let tag = format!(
                "qLogNEI case {k} (incr={}, infeasible samples={})",
                c.incremental, c.infeasible_samples
            );
            r.check(&f.name, &format!("{tag} value"), log_err(v, c.value), RTOL);
            r.check_slices_atol(
                &f.name,
                &format!("{tag} grad"),
                &matrix_rows(&g),
                &flatten(&c.grad),
                RTOL,
                GRAD_ATOL,
            );
        }
    }
    assert!(
        infeasible_cases >= 3,
        "the fixtures must cover infeasible baselines"
    );
    r.finish("qLogNEI with objectives and constraints");
}

#[test]
fn parity_prune_and_infeasible_cost() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let x = matrix(&f.prune.x);
        for (k, c) in f.prune.cases.iter().enumerate() {
            let z = matrix(&c.base_samples);
            let options = PruneOptions {
                num_samples: z.nrows(),
                base_samples: Some(z),
                objective: c.objective.as_ref().map(build_objective),
                constraints: c
                    .constraints
                    .as_ref()
                    .map(|cs| cs.iter().map(build_constraint).collect()),
                ..Default::default()
            };
            let idx = prune_inferior_points_indices(model.as_ref(), &x, &options).unwrap();
            assert_eq!(idx, c.indices, "{}: prune case {k}", f.name);
        }
        let xc = matrix(&f.prune.infeasible_cost_x);
        for c in &f.prune.infeasible_cost {
            let obj = c.objective.as_ref().map(build_objective);
            let v = get_infeasible_cost(model.as_ref(), obj.as_deref(), &xc).unwrap();
            r.check_slices(&f.name, "infeasible cost", &[v], &[c.value], RTOL);
        }
    }
    r.finish("prune_inferior_points with constraints, get_infeasible_cost");
}
